    with get_session() as session:
        existing = session.exec(
            select(StrategyRecord).where(StrategyRecord.strategy_id == strategy.strategy_id)
        ).first()
        fields = {
            "name": strategy.name,
            "source": strategy.source,
            "market": strategy.market,
            "frequency": strategy.frequency,
            "status": "compiled",
