            "risk_rule": strategy.risk_rule,
            "constraints": strategy.constraints,
            "tags": strategy.tags,
            "updated_at": _now(),
        }
        if existing:
            for key, value in fields.items():
                setattr(existing, key, value)
            session.add(existing)
        else:
